        assert_eq!(civil_from_unix_days(-1), (1969, 12, 31));
        assert_eq!(civil_from_unix_days(10_957), (2000, 1, 1));
        assert_eq!(format_date_picture("yyyy", 1970, 1, 1), "1970");
