        assert!(pts.len() > 8, "arcs must add vertices; n={}", pts.len());
        assert!(
            pts.iter().any(|(x, y)| (*x - r).abs() < 0.05 && *y < 0.05),
            "bottom edge starts after radius; {pts:?}"
        );
        let sharp_corner = pts.iter().any(|(x, y)| x.abs() < 0.05 && y.abs() < 0.05);
